 */
class Certification extends Model
{
    use \AtrioTeam\Marvin\App\Models\CommonTrait;
    use OnPageTrait;
    use SoftDeletes;

    /**
     * revisionable configuration
     */
    use \Venturecraft\Revisionable\RevisionableTrait;
    protected $revisionForceDeleteEnabled = true;
    protected $revisionCreationsEnabled = true;


    /**
     * The table associated with the model.
     *
     * @var string
     */
    protected $table = 'certifications';


    /**
     * The attributes that are mass assignable.
     *
     * @var array
     */
    protected $fillable = [];


    public function langs()
    {
        return $this->hasMany(CertificationLang::class, "item_id");
    }


    /**
     * Map remote OnPage fields to local ones.
     */
    public function onPageUpdateFromRemote(Thing $remoteItem, Resource $remoteResource): self
    {
        $this->onPageUpdateDefault($remoteItem, $remoteResource);

        $this->save();


        // create or update local subcategory lang
        foreach (config('marvin.locales') as $localeId =>  $localeInfo) {
            $localItemLang = CertificationLang::firstOrNew([
                'lang' => $localeId,
                'item_id' => $this->id,
            ]);

            $localItemLang->onpage_raw = $this->collectTranslatableFields($localItemLang, $localeInfo[0], $remoteItem, $remoteResource, true);

            $title = ucfirst(strtolower($remoteItem->val('nome', $localeInfo[0])));

            // maps local attributes to remote ones
            $attributes = [
                'title' => $title,
            ];

            // by default, leave local data if any
            foreach ($attributes as $key => $remoteValue) {
                $localItemLang->$key = $remoteValue;
            }


            $localItemLang->save();
        }


        return $this;
    }


    /**
     * Products that certifications are related to
     */
    public function products(): BelongsToMany
    {
        return $this->belongsToMany(Product::class, 'products_rel_certifications', 'certification_id', 'product_id')->withTimestamps();
    }
}
